<?php
namespace Ishep\Repositories;
use PDO;
final class UserRepository { public function __construct(private PDO $db){} public function byEmail(string $email):?array{$s=$this->db->prepare('SELECT * FROM users WHERE email = ? LIMIT 1');$s->execute([$email]);return$s->fetch()?:null;} public function byId(int $id):?array{$s=$this->db->prepare('SELECT * FROM users WHERE id = ?');$s->execute([$id]);return$s->fetch()?:null;} public function create(string $name,string $email,string $hash):int{$s=$this->db->prepare("INSERT INTO users (name,email,password,account_status,created_at,updated_at) VALUES (?,?,?,'active',UTC_TIMESTAMP(),UTC_TIMESTAMP())");$s->execute([$name,$email,$hash]);return(int)$this->db->lastInsertId();} public function loginAt(int $id):void{$this->db->prepare('UPDATE users SET last_login_at=UTC_TIMESTAMP(), updated_at=UTC_TIMESTAMP() WHERE id=?')->execute([$id]);} public function password(int $id,string $hash):void{$this->db->prepare('UPDATE users SET password=?, remember_token=NULL, updated_at=UTC_TIMESTAMP() WHERE id=?')->execute([$hash,$id]);} }
